/* generated by tools/make_voices.py: voice sprite timings and lip-sync envelopes (30 fps) */
const VOICE_DATA = {"file":"voice/ep01x.mp3","lines":{"c1":{"who":"AKURO","text":"Tell me, boy...","mono":false,"off":0.25,"dur":1.131,"env":"0015599797887447899755543321000000"},"c2":{"who":"AKURO","text":"...what is it you want to break?","mono":false,"off":1.781,"dur":1.6,"env":"003577976864357424674678763223256664321000000000"},"c3":{"who":"TAKUTO","text":"Everything that's in the way.","mono":false,"off":3.781,"dur":1.557,"env":"06962597114966655887315356555458663111000000000"},"e1":{"who":"TAKUTO","text":"Two-fourteen. Last freight of the night.","mono":true,"off":5.738,"dur":2.005,"env":"0236511169830324444322223566433110355443123344432100000000000"},"e2":{"who":"TAKUTO","text":"Same crossing. Same bell.","mono":true,"off":8.143,"dur":1.728,"env":"0011866654111798742224321100124655554246432100000000"},"e3":{"who":"TAKUTO","text":"Same cat.","mono":true,"off":10.271,"dur":0.917,"env":"0022697766312797542100000000"},"e4":{"who":"TAKUTO","text":"It was Haruki's cat first. He fed it every night on his way home.","mono":true,"off":11.588,"dur":4.373,"env":"056246532127998666520110333333301254410011277531112310000000000003421189848523562244454555443101344433212433332245542110000000000000"},"e5":{"who":"TAKUTO","text":"Two years now.","mono":true,"off":16.361,"dur":0.981,"env":"132753478996324665432110000000"},"e6":{"who":"TAKUTO","text":"So I bring the cat food. Somebody has to.","mono":true,"off":17.742,"dur":2.752,"env":"01247798932776664125765101114654322110000000124896657765543345655343002210000000000"},"e7":{"who":"TAKUTO","text":"Tuna. The expensive kind. Don't tell anyone.","mono":false,"off":20.894,"dur":2.901,"env":"0317766664146784145204765233521023667643221100000000397530426777424554433221100000000000"},"e8":{"who":"TAKUTO","text":"Grandma used to say I was born to carry things for other people.","mono":true,"off":24.195,"dur":4.011,"env":"0278999976797775433566451134544476655300366644532111677866544122101155554400055433332311352045344201133300111000000000000"},"e9":{"who":"TAKUTO","text":"...What is it?","mono":false,"off":28.606,"dur":0.875,"env":"002359858643354320000000000"},"e10":{"who":"TAKUTO","text":"The bell... There's no train.","mono":true,"off":29.881,"dur":1.664,"env":"03321999876530005543325655420332355432110000000000"},"e11":{"who":"TAKUTO","text":"...Okay. No.","mono":false,"off":31.945,"dur":1.067,"env":"003894032898655666664321100000000"},"e12":{"who":"???","text":"Don't come near it!","mono":false,"off":33.412,"dur":1.173,"env":"053995102336988877775432210240000000"},"e13":{"who":"TAKUTO","text":"Hey!","mono":false,"off":34.985,"dur":0.576,"env":"003999865432100000"},"e14":{"who":"TAKUTO","text":"Get down!","mono":false,"off":35.961,"dur":0.768,"env":"026400497665432211000000"},"a1":{"who":"TAKUTO","text":"...Two moons.","mono":true,"off":37.129,"dur":0.981,"env":"000347986689987543321221000000"},"a2":{"who":"TAKUTO","text":"Okay. That's new.","mono":true,"off":38.51,"dur":1.173,"env":"268822269998279831434675421010000000"},"a3":{"who":"TAKUTO","text":"And I'm holding... an axe?","mono":true,"off":40.083,"dur":1.643,"env":"04577876531399886244322100000354346532100233200000"},"a4":{"who":"TAKUTO","text":"Where the hell am I?","mono":true,"off":42.126,"dur":1.131,"env":"0048557434899775665554211100000000"},"a5":{"who":"NEMU","text":"Hnnnaaah... Oh. You're alive. Neat.","mono":false,"off":43.657,"dur":2.453,"env":"02550144113555420010000000000006996432014444343332211000000245642100022000"},"a6":{"who":"TAKUTO","text":"You were lying on train tracks a minute ago.","mono":false,"off":46.5099,"dur":2.304,"env":"0144794588887765455532325555541322654302434554442411454321000000000000"},"a7":{"who":"NEMU","text":"Mm. I'm very good at that.","mono":false,"off":49.2139,"dur":1.941,"env":"02488888775531000000001399932677676103775440024322100041000"},"a8":{"who":"NEMU","text":"Lying places. Getting squished.","mono":false,"off":51.5549,"dur":2.368,"env":"002789999874040555422222221221000000000003799387743332117742102333102000"},"a9":{"who":"TAKUTO","text":"Where is this?","mono":false,"off":54.3229,"dur":1.003,"env":"0267999899642159753122210000000"},"a10":{"who":"NEMU","text":"The Barrow Fields. Edge of the Ashen March.","mono":false,"off":55.7258,"dur":3.157,"env":"01307977766641111465431000002320000000000000000049996213322310552047753433245555433211000232100"},"a11":{"who":"NEMU","text":"You fell out of the sky.","mono":false,"off":59.2828,"dur":1.472,"env":"006721117998753027984400145341365432110000000"},"a12":{"who":"NEMU","text":"People like you have a name here. Skyfallen.","mono":false,"off":61.1548,"dur":3.157,"env":"02269105886678860021773467166778888751134321100000000000000000000001345245999831125332221100000"},"a13":{"who":"TAKUTO","text":"There are others?","mono":false,"off":64.7118,"dur":0.981,"env":"006788885169927653322221000000"},"a14":{"who":"NEMU","text":"A few. Most of them land worse.","mono":false,"off":66.0928,"dur":2.197,"env":"031101179842000000000028996340440034543334555544420153211002332100"},"a15":{"who":"TAKUTO","text":"...I'll take that as a compliment.","mono":false,"off":68.6898,"dur":1.707,"env":"0027981348995100488756544411246652134322100000000000"},"a16":{"who":"NEMU","text":"...Hey.","mono":false,"off":70.7968,"dur":0.683,"env":"012112998654321000000"},"a17":{"who":"NEMU","text":"Where did you get that axe?","mono":false,"off":71.8798,"dur":1.365,"env":"00595782458424851014654103663210012332000"},"a18":{"who":"TAKUTO","text":"It was sticking out of a grave. I grabbed it on the way down.","mono":false,"off":73.6448,"dur":3.413,"env":"0463657631990135666662252126877543211000000000000047732139999993236545555554354443246654211000000000000"},"a19":{"who":"NEMU","text":"That's the Headsman's Axe.","mono":false,"off":77.4578,"dur":1.429,"env":"0168503205843797142466544302774210002221000"},"a20":{"who":"NEMU","text":"It's been stuck in that grave for three hundred years.","mono":false,"off":79.2868,"dur":3.371,"env":"033031049763222203763100125544443000114443211100000000000000000004300115774127552332012332100002321000"},"a21":{"who":"NEMU","text":"People tried pulling it out with horses.","mono":false,"off":83.0578,"dur":2.688,"env":"010750255302321676532111010000000000218999877626665531001311025543343211000222100"},"a22":{"who":"TAKUTO","text":"...It was loose.","mono":false,"off":86.1458,"dur":0.939,"env":"04664653345798632112210000000"},"a23":{"who":"NEMU","text":"WHY WAS IT LOOSE?!","mono":false,"off":87.4848,"dur":1.237,"env":"00279984299535620048974201333310000000"},"a24":{"who":"NEMU","text":"Rifts open in the sky. Things crawl out.","mono":false,"off":89.1218,"dur":3.008,"env":"0089610112320089840034332345444330343221110000000000000000000498764401146543343321100020000"},"a25":{"who":"NEMU","text":"We call them Fiends.","mono":false,"off":92.5298,"dur":1.259,"env":"00750434988814865211168764321112333100"},"a26":{"who":"NEMU","text":"Swords don't bite them. Arrows bounce off.","mono":false,"off":94.1888,"dur":3.157,"env":"01223666766303314674100555430001211110000000000000000000015997666543430255554313333221110000000"},"a27":{"who":"NEMU","text":"Normal people can't do anything but run.","mono":false,"off":97.7458,"dur":2.773,"env":"005788776530021342021100000000002117631053550069765200123221000002310026653210000000"},"a28":{"who":"NEMU","text":"Unless you have a Brand.","mono":false,"off":100.9188,"dur":1.451,"env":"02998788723333313632461051045665421000021000"},"a29":{"who":"NEMU","text":"A mark on your soul. It wakes up when you're about to die... if you have one.","mono":false,"off":102.7698,"dur":5.333,"env":"0137778778653000101986565454434432200000000000000000000000000000047200699502333367510014776666633654200423045543322110000000000000001611136323455541101111000000"},"a30":{"who":"NEMU","text":"Branded people become Hunters. They hunt Fiends for the Guild.","mono":false,"off":108.5028,"dur":4.181,"env":"024788864452001205301222100330213544211166522411000024320000000000000000000001431299521000028998654323420040420354321100010000"},"a31":{"who":"TAKUTO","text":"And people without one?","mono":false,"off":113.0838,"dur":1.387,"env":"026613367501998357437888631344321000000000"},"a32":{"who":"NEMU","text":"Get very good at running.","mono":false,"off":114.8708,"dur":1.472,"env":"033721111699878840032698744300287742210000000"},"a33":{"who":"NEMU","text":"Mine's called Nine Lives.","mono":false,"off":116.7428,"dur":1.728,"env":"0037999864453032676600056987776443443321100001633000"},"a34":{"who":"NEMU","text":"I can die nine times. I've used six.","mono":false,"off":118.8708,"dur":3.243,"env":"02440328974587666665557666665331233432211100332000000000000000000049921159974330133326310022221000"},"a35":{"who":"TAKUTO","text":"Six.","mono":false,"off":122.5138,"dur":0.619,"env":"0012599741111010000"},"a36":{"who":"NEMU","text":"Don't make the face.","mono":false,"off":123.5328,"dur":1.216,"env":"0479974128873010341113643211012221000"},"a37":{"who":"TAKUTO","text":"I'm not making a face.","mono":false,"off":125.1488,"dur":1.365,"env":"05667699943674115454110387531112221000000"},"a38":{"who":"NEMU","text":"You're making it with your eyes.","mono":false,"off":126.9138,"dur":1.643,"env":"00498989985022565442010042124410476432100002332000"},"a39":{"who":"TAKUTO","text":"That thing at the crossing. Was it chasing you?","mono":false,"off":128.9568,"dur":2.581,"env":"005992001976673052124899633233221100000025734720244387543324443322110000000000"},"a40":{"who":"NEMU","text":"I was digging for grave silver. It woke up. Shieldbearers don't wake up.","mono":false,"off":131.9378,"dur":5.355,"env":"00267445321049931565441113100215665555124232443210211100000000000000000002610067740315421100110000000000000000002343699751046443232212330357631145410233210001000"},"a41":{"who":"NEMU","text":"Then the ground opened. Rifts open in the sky... not into other worlds.","mono":false,"off":137.6928,"dur":5.525,"env":"0158766462114666554443501553003100001100000000000000000000002897310101223000278730034433245433432202443322111000000000000000000037655423544220265144213322100000233100"},"a42":{"who":"NEMU","text":"Somebody opened that one.","mono":false,"off":143.6178,"dur":1.835,"env":"01233788746655233100000000049840246542444310011111000000"},"a43":{"who":"TAKUTO","text":"...You hear that?","mono":false,"off":145.8528,"dur":0.917,"env":"0035422678944765321000000000"},"a44":{"who":"NEMU","text":"A bell. There are no bells out here.","mono":false,"off":147.1698,"dur":2.048,"env":"01410998642100000000013169878999610866544454332203114221110000"},"b1":{"who":"NEMU","text":"Run. I mean it this time.","mono":false,"off":149.6178,"dur":1.685,"env":"004998754200000035876689966300253444141322111000000"},"b2":{"who":"TAKUTO","text":"You said that at the crossing.","mono":false,"off":151.7028,"dur":1.472,"env":"013332298521666554013001455542212110000000000"},"b3":{"who":"NEMU","text":"And you didn't listen! I only have three left!","mono":false,"off":153.5748,"dur":2.837,"env":"00034553681540258443311210000000000000000002563069888762245521101136553333211000002000"},"b4":{"who":"TAKUTO","text":"Then stay behind me.","mono":false,"off":156.8118,"dur":1.387,"env":"005665343079976218522256655432210000000000"},"b5":{"who":"NEMU","text":"Don't hit the shield! Nothing breaks the shield!","mono":false,"off":158.5988,"dur":2.773,"env":"032641113930024443326654211010000000000000016998311887643665113200444315432110010000"},"b6":{"who":"TAKUTO","text":"Then what do I hit?!","mono":false,"off":161.7718,"dur":1.216,"env":"0045555994014667754313553100121000000"},"b7":{"who":"NEMU","text":"Nothing! We run!","mono":false,"off":163.3878,"dur":1.045,"env":"00698311688741006741665321000000"},"b8":{"who":"TAKUTO","text":"Can't... get up...","mono":true,"off":164.8328,"dur":1.301,"env":"0012488777630121498667864300000000000000"},"b9":{"who":"NEMU","text":"Hey! Ugly!","mono":false,"off":166.5338,"dur":0.896,"env":"001577642001895223331100000"},"b10":{"who":"NEMU","text":"Over here!","mono":false,"off":167.8298,"dur":0.789,"env":"039822642217875422100000"},"b11":{"who":"TAKUTO","text":"Wait!","mono":false,"off":169.0188,"dur":0.555,"env":"02798654101100000"},"b12":{"who":"TAKUTO","text":"Born to carry things for other people.","mono":true,"off":169.9738,"dur":2.432,"env":"0116999887535401257766552110665444434213541553553011344200232110000000000"},"b13":{"who":"TAKUTO","text":"Groceries. Grudges. Blame.","mono":true,"off":172.8058,"dur":2.027,"env":"0003799843323344432200147874212443220003455543210000000000000"},"b14":{"who":"TAKUTO","text":"Not this. I'm not carrying this one.","mono":true,"off":175.2328,"dur":2.261,"env":"01346785000489633321003444454310114444443333233231023210000000000000"},"b15":{"who":"AKURO","text":"Finally.","mono":false,"off":177.8938,"dur":0.875,"env":"002499767576554554211000000"},"b16":{"who":"AKURO","text":"Three hundred years in the dirt, and this is who pulls me out?","mono":false,"off":179.1688,"dur":3.968,"env":"000145675543358854369532347775788532245555421368898542000000245654567743333211356433224431001355454223454445543221000000"},"b17":{"who":"TAKUTO","text":"Who are you?","mono":false,"off":183.5368,"dur":0.875,"env":"000577997533567431110000000"},"b18":{"who":"AKURO","text":"The reason the axe was stuck.","mono":false,"off":184.8118,"dur":1.792,"env":"013994566676534766575435666421125432221477642100000000"},"b19":{"who":"AKURO","text":"Tell me, boy. What is it you want to break?","mono":false,"off":187.0038,"dur":2.411,"env":"0134577889986446889886553200235886995554223686566522221477653320001100000"},"b20":{"who":"TAKUTO","text":"Everything that's in the way.","mono":false,"off":189.8148,"dur":1.557,"env":"06962597115966655887316456655458664111000000000"},"b21":{"who":"AKURO","text":"...Good answer.","mono":false,"off":191.7718,"dur":1.088,"env":"013379877645777643334654432100000"},"b22":{"who":"TAKUTO","text":"It was in the way.","mono":false,"off":193.2598,"dur":1.131,"env":"0652496559787775458986311100000000"},"b23":{"who":"NEMU","text":"Hnnaaah... Ow.","mono":false,"off":194.7908,"dur":1.493,"env":"027640343125555422112100000000005986421000000"},"b24":{"who":"TAKUTO","text":"You were dead.","mono":false,"off":196.6838,"dur":0.896,"env":"013545742189887532100000000"},"b25":{"who":"NEMU","text":"Mm. That's seven. Two left.","mono":false,"off":197.9798,"dur":2.155,"env":"02697777766442100145301333256510311000000000431865343321100002000"},"b26":{"who":"TAKUTO","text":"Don't do that again.","mono":false,"off":200.5348,"dur":1.237,"env":"01897430367628765442135543210000000000"},"b27":{"who":"NEMU","text":"You're making the face.","mono":false,"off":202.1718,"dur":1.237,"env":"00598898970316654431114542100023221000"},"b28":{"who":"TAKUTO","text":"I'm making it with my whole face this time.","mono":false,"off":203.8088,"dur":2.539,"env":"03777668898201355555311330365553126988621116654334202334112554311000000000000"},"b29":{"who":"TAKUTO","text":"...I never asked your name.","mono":false,"off":206.7477,"dur":1.451,"env":"00357778953997666463024455555432100000000000"},"b30":{"who":"NEMU","text":"Nemu.","mono":false,"off":208.5987,"dur":0.875,"env":"000599998778753211110000000"},"b31":{"who":"NEMU","text":"And you're the idiot who pulled out the Headsman's Axe.","mono":false,"off":209.8738,"dur":2.965,"env":"00465457662240005971321100001000000000000410213553254320132124412303433231133210001122100"},"b32":{"who":"TAKUTO","text":"Takuto. Kirishima Takuto.","mono":false,"off":213.2388,"dur":2.283,"env":"036630054126987532100014434354244444443002443101320223432110000000000"},"b33":{"who":"SIEG","text":"Well, well, well.","mono":false,"off":215.9218,"dur":1.429,"env":"0697665666787765556676300279877644432100000"},"b34":{"who":"SIEG","text":"A Shieldbearer's shield. Broken in one swing.","mono":false,"off":217.7508,"dur":3.008,"env":"0597444797776656776677643333676676544431000000000998741397656777766766654331487654322110000"},"b35":{"who":"SIEG","text":"Twelve years I've been hunting. Never seen that.","mono":false,"off":221.1587,"dur":3.179,"env":"024976655766665555542100004677532766652276553267544331000000008977457653322777776545443310110000"},"b36":{"who":"SIEG","text":"Nice axe, kid. Mind telling me where you got it?","mono":false,"off":224.7378,"dur":3.093,"env":"288666643102676420133101597764342000000000697666666413296556666665566566653376555423421110000"},"b37":{"who":"TAKUTO","text":"It was loose.","mono":false,"off":228.2308,"dur":0.917,"env":"0443552244698642111110000000"},"b38":{"who":"NEMU","text":"He keeps saying that.","mono":false,"off":229.5478,"dur":1.451,"env":"00094042796044335898766554554321002100000000"},"b39":{"who":"SIEG","text":"Ha! It was loose, he says.","mono":false,"off":231.3988,"dur":1.792,"env":"017987666641047458867999877762210019963278655433210000"},"b40":{"who":"SIEG","text":"You two had better come with me. Because that...","mono":false,"off":233.5908,"dur":2.795,"env":"088741327765566677554256546652012765455664105654443100000005842997544776543202211000"},"b41":{"who":"SIEG","text":"...is not supposed to stay open.","mono":false,"off":236.7858,"dur":1.984,"env":"069878976563123286219766764101475320577652367762054332210000"},"b42":{"who":"AKURO","text":"We're going to have so much fun, you and I.","mono":false,"off":239.1697,"dur":2.603,"env":"0149736887643454577633444697756743321136765552321013489865664223555432211000000"},"s1":{"who":"SABLE","text":"One fell through.","mono":false,"off":242.1728,"dur":1.856,"env":"00012479765221246443223311133322222100000000000000000000"},"s2":{"who":"SABLE","text":"...Good.","mono":false,"off":244.4288,"dur":1.045,"env":"01211442137975432220111111100000"},"p1":{"who":"TAKUTO","text":"Next time: the Hunters' Guild.","mono":false,"off":245.8738,"dur":1.728,"env":"0258821531499977653354257632365331158863211000000000"},"p2":{"who":"TAKUTO","text":"A test that reads my rank as ERROR...","mono":false,"off":248.0017,"dur":2.133,"env":"0310427973310652124452113544432444443013322103444321100000000000"},"p3":{"who":"TAKUTO","text":"...and a girl with a red scarf who hates me on sight.","mono":false,"off":250.5348,"dur":2.859,"env":"00046674226999997435315323656412442036676431103322354302134333332233254210000000000000"},"p4":{"who":"TAKUTO","text":"Why does she have my hair?","mono":false,"off":253.7937,"dur":1.493,"env":"004798938554345557721355444214654211000000000"},"p5":{"who":"TAKUTO","text":"Episode two. Branded.","mono":false,"off":255.6867,"dur":1.621,"env":"0451143349974103327653211000026655654322110000000"},"ep01x_001":{"who":"TAKUTO","text":"My name is Takuto Kirishima. Seventeen. Nerima ward, Tokyo.","mono":false,"off":257.7077,"dur":5.248,"env":"01366555555555432234201465201320234541011033223323432233322211000000000023379623431223433211000000024555533445445455532245555432000224431001222210000000000000"},"ep01x_002":{"who":"TAKUTO","text":"I go to school. I sleep in class. I get into fights I do not start, and finish them anyway.","mono":false,"off":263.3558,"dur":5.867,"env":"00144218998453340014555443321000134433320244300233330101555321101111000000000000144228655554111057555202344313334444202330365554320122100343323102332101344432121100000000000000"},"ep01x_003":{"who":"TAKUTO","text":"Two years ago, my best friend walked to the railway crossing to feed a stray cat, and never came home.","mono":false,"off":269.6224,"dur":6.101,"env":"0326644479974474227665543344452138773431110655444322577400023144224556554234330011266643333331122100233243553013544310114663100000000000000146556651440112443433135653210000000000000000"},"ep01x_004":{"who":"TAKUTO","text":"I still go every night. Somebody has to feed the cat.","mono":false,"off":276.1237,"dur":3.413,"env":"0355541199862279896245622445555564210000000000013489765797454455543024111034343113011355321000000000000"},"ep01x_005":{"who":"HARUKI","text":"Your knuckles are bleeding.","mono":false,"off":279.9371,"dur":1.643,"env":"03699877799602477655456775425666776354322221000000"},"ep01x_006":{"who":"TAKUTO","text":"They started it.","mono":false,"off":281.9798,"dur":1.109,"env":"0046744430599998755532321100000000"},"ep01x_007":{"who":"HARUKI","text":"There were three of them, and they are in high school, and you are fourteen. They definitely started it. You definitely finished it.","mono":false,"off":283.4891,"dur":5.888,"env":"049976874011577774456554235667665677665641365555542016655444465566566420006775213154322210000047752487411676213565430588774541220000000000017853487511676213553027554430131000000"},"ep01x_008":{"who":"TAKUTO","text":"Why did you stop me?","mono":false,"off":289.7771,"dur":1.323,"env":"0126899968334545309877610133211100000000"},"ep01x_009":{"who":"HARUKI","text":"Because they got it. You were just going to keep going. You looked like you would keep going forever.","mono":false,"off":291.4998,"dur":4.565,"env":"05942797551587553287777645420004775654465531476665443022664100387653212110000000005876872025765225656530216620027665553114666652232100000"},"ep01x_010":{"who":"TAKUTO","text":"...Nobody ever stops me.","mono":false,"off":296.4651,"dur":1.621,"env":"0245679528846432562243431165553012123210000000000"},"ep01x_011":{"who":"HARUKI","text":"Then I will. Haruki Shinjo. Class two-B. You are Kirishima, right? Everybody is scared of you.","mono":false,"off":298.4864,"dur":5.099,"env":"039787675367655421586676411255533327766543554211100015864420318753453210000006787401256545653325666655544566641000068437853666454444332026675342122110000"},"ep01x_012":{"who":"TAKUTO","text":"You are not.","mono":false,"off":303.9851,"dur":0.896,"env":"002568976788986421013100000"},"ep01x_013":{"who":"HARUKI","text":"I am terrified. I just hide it well. Hey, look. Behind the vending machine.","mono":false,"off":305.2811,"dur":3.968,"env":"188887773445889951167666532576466611177785731377653222100000000019987666974111006766877777547877656565544433543221100000"},"ep01x_014":{"who":"HARUKI","text":"A cat. It watched the whole fight.","mono":false,"off":309.6491,"dur":1.877,"env":"088422797777632147666878743138767877421187643221321000000"},"ep01x_015":{"who":"TAKUTO","text":"It looks hungry.","mono":false,"off":311.9264,"dur":1.088,"env":"046349812522597665244332110000000"},"ep01x_016":{"who":"HARUKI","text":"What do cats drink? Milk?","mono":false,"off":313.4144,"dur":1.685,"env":"036985347642288762431147776542236776543101112100000"},"ep01x_017":{"who":"TAKUTO","text":"The machine only has coffee milk.","mono":false,"off":315.4998,"dur":1.813,"env":"0345645425666543245544553301217982103332321100000000000"},"ep01x_018":{"who":"HARUKI","text":"Then it is getting coffee milk. Terrible idea. Let us do it.","mono":false,"off":317.7131,"dur":3.179,"env":"029999667541575666512289741176766542101000000326988864676566665357765433235765654026653311110000"},"ep01x_019":{"who":"HARUKI","text":"Ha! It likes it! It actually likes it!","mono":false,"off":321.2917,"dur":2.219,"env":"0018988788446877742436763105864477632325667756766532324332101000000"},"ep01x_020":{"who":"TAKUTO","text":"It is making a face.","mono":false,"off":323.9104,"dur":1.344,"env":"05776885447875015555100498521102211000000"},"ep01x_021":{"who":"HARUKI","text":"We should name it. I am calling it Mister Tuesday. I met it on a Tuesday.","mono":false,"off":325.6544,"dur":3.861,"env":"06985468568776667776410027776664131887666663246653136304177765411533222000000005887777746577564131766542034222110000"},"ep01x_022":{"who":"TAKUTO","text":"That is a terrible name.","mono":false,"off":329.9158,"dur":1.472,"env":"004895674451141467883245455555432100000000000"},"ep01x_023":{"who":"HARUKI","text":"What would you call it?","mono":false,"off":331.7878,"dur":1.301,"env":"0579983368657852335877865544212222100000"},"ep01x_024":{"who":"TAKUTO","text":"...Coffee.","mono":false,"off":333.4891,"dur":0.811,"env":"0011369984112553311100000"},"ep01x_025":{"who":"HARUKI","text":"That is worse! That is so much worse!","mono":false,"off":334.6997,"dur":2.005,"env":"0269985776576677787654200775654227666632225675432222221000000"},"ep01x_026":{"who":"HARUKI","text":"Same time tomorrow? Somebody has to feed it.","mono":false,"off":337.1051,"dur":2.624,"env":"0233987666226766656422776666776654322232676655864555565301541004766523210000000"},"ep01x_027":{"who":"TAKUTO","text":"...Same time tomorrow.","mono":false,"off":340.1291,"dur":1.451,"env":"01235977641346766542224555665432221000000000"},"ep01x_028":{"who":"HARUKI","text":"You are late. You are always late. The cat is going to give up on us.","mono":false,"off":341.9798,"dur":3.413,"env":"0279877765577775200268776426776466654245765320100000000562226888456541676655437636641165543321233220000"},"ep01x_029":{"who":"TAKUTO","text":"Ten minutes. My dad caught me on the stairs.","mono":false,"off":345.7931,"dur":2.517,"env":"0137666678765420131013555314877762102289512344433333420565431100011100000000"},"ep01x_030":{"who":"HARUKI","text":"Takuto. The sky looks weird tonight. Is it supposed to crackle like that?","mono":false,"off":348.7104,"dur":3.968,"env":"028986215985228876644336533177667656752331467666422266654331000000000037664335631876652144121867521554544203544320000000"},"ep01x_031":{"who":"TAKUTO","text":"Crackle?","mono":false,"off":353.0784,"dur":0.725,"env":"0027987501476433200000"},"ep01x_032":{"who":"HARUKI","text":"There is a crack in it. Takuto, there is a crack in the\u2014","mono":false,"off":354.2038,"dur":2.816,"env":"0399888667521226877411777642100002898411886338776554666654631239776313666543322210000"},"ep01x_033":{"who":"TAKUTO","text":"When I got there, there was a bag of cat food on the ground, and nobody else.","mono":false,"off":357.4198,"dur":4.331,"env":"0035677621798850005644443135443453115555541521011245300111254442444343113555543211000000000004666666731444333344421002333100000000"},"ep01x_034":{"who":"CROWD2","text":"Takuto? Is that you? Out so late again?","mono":false,"off":362.1504,"dur":2.624,"env":"1189610474225665542242206865112234333221003666301224442254424213333211100000000"},"ep01x_035":{"who":"TAKUTO","text":"Mrs. Shinjo. You are putting up posters at one in the morning?","mono":false,"off":365.1744,"dur":3.84,"env":"01465332664233323245555322444211100000000002478500259554566000113664232013322343211244443333334444442110000000000000"},"ep01x_036":{"who":"CROWD2","text":"The old ones get wet. Nobody reads a wet poster.","mono":false,"off":369.4144,"dur":2.987,"env":"037749999624886753127632268974112100245878628846542345413542586100035542222233321000000000"},"ep01x_037":{"who":"CROWD2","text":"Two years. Nobody calls anymore. Not even the police.","mono":false,"off":372.8011,"dur":3.093,"env":"042876445766663212467772487352011587632353432344454321000138994652234520034344322122221000000"},"ep01x_038":{"who":"TAKUTO","text":"I will help.","mono":false,"off":376.2944,"dur":0.853,"env":"00578697546999641000000000"},"ep01x_039":{"who":"CROWD2","text":"You always say that. You are a good boy, Takuto. He always said so.","mono":false,"off":377.5478,"dur":3.733,"env":"0378699956774322666515755530000014788887312894213656655303168510252324554321245765244332225631222333321000000000"},"ep01x_040":{"who":"CROWD2","text":"Are you still feeding the cat?","mono":false,"off":381.6811,"dur":1.707,"env":"0598645542211676631003344443333013555542000000000000"},"ep01x_041":{"who":"TAKUTO","text":"Every night.","mono":false,"off":383.7878,"dur":0.875,"env":"169624766678875321011000000"},"ep01x_042":{"who":"CROWD2","text":"Then he will know where to find you. When he comes back.","mono":false,"off":385.0624,"dur":2.645,"env":"01597777467557877555534111755443232333221000136555302266333303976531000000000000"},"ep01x_043":{"who":"CROWD2","text":"Go on. It is almost two. Do not keep it waiting.","mono":false,"off":388.1078,"dur":2.688,"env":"017988677666654202545533663344322204134433321234774001320332244433222111000000000"},"ep01x_044":{"who":"TAKUTO","text":"...Good night, Mrs. Shinjo.","mono":false,"off":391.1957,"dur":1.771,"env":"001597246764212342213211112122344431244332110000000000"},"ep01x_045":{"who":"SIEG","text":"Proper introductions, then. Sieg Valen. Hunter, rank A. Some people call me the Laughing Blade. I do not know why.","mono":false,"off":393.3664,"dur":7.339,"env":"02976205666643464765203536766542057665555420000000024339755565865555665544100000017766335765556666662146654430000000000023387654118751166410267556664465555553115666426666544443100000000168667776552006766654444433221110000"},"ep01x_046":{"who":"NEMU","text":"He winks a lot.","mono":false,"off":401.1051,"dur":1.088,"env":"000684698623232432343321100021000"},"ep01x_047":{"who":"SIEG","text":"I wink exactly the right amount.","mono":false,"off":402.5931,"dur":2.347,"env":"08999998777411038868679776300278887620000099998767637988876544321310000"},"ep01x_048":{"who":"TAKUTO","text":"Takuto Kirishima. I fell out of the sky.","mono":false,"off":405.3397,"dur":3.072,"env":"036640146215998301004443343243334444332211000000000355111388665543213332035454221000000000000"},"ep01x_049":{"who":"SIEG","text":"I noticed. A Skyfallen. You came through a Rift. The crack you saw in your sky. They open over this world, and Fiends crawl out of them.","mono":false,"off":408.8118,"dur":8.235,"env":"05898765655654320000026544301655565104765555454300000007842697666411178766555567553101001000000000000661249753100587433266555556665543331056555544442000000000078402676305655565575466532047665555531015641005776666554320012766555424555453223322200000"},"ep01x_050":{"who":"TAKUTO","text":"The skeleton with the shield.","mono":false,"off":417.4464,"dur":1.451,"env":"02222069966621444341023222134333111000000000"},"ep01x_051":{"who":"SIEG","text":"A Skeletal Shieldbearer. Lesser class. The weakest Fiend you will ever meet. You just broke its shield, which nobody has ever done.","mono":false,"off":419.2971,"dur":7.68,"env":"066442067656656765333347766654376555555420000038863367401258776443233220000000000049889642048631110787666567656531465566677653111000000000001996786410029766510652233336766655554200000673341898666556545566774202674565326654322210000"},"ep01x_052":{"who":"TAKUTO","text":"It was in the way.","mono":false,"off":427.3771,"dur":1.131,"env":"0652496458787775458886311100000000"},"ep01x_053":{"who":"SIEG","text":"Ha! It was in the way. I like you.","mono":false,"off":428.9078,"dur":2.219,"env":"0159766664541388678777776676666655530000005898876664211265433210000"},"ep01x_054":{"who":"SIEG","text":"Ordinary weapons barely scratch a Fiend. To hurt one, you need a Brand. A power carved into your soul. It shows up as a mark.","mono":false,"off":431.5264,"dur":8.085,"env":"277644555444455545540055555431002655544554332016543032531005665543332100000000001786596530025654431005666655445431665554433322000000000000046201346444455541012654455432455424455533322655543322100000000046344336655644653003444655544332100000000"},"ep01x_055":{"who":"SIEG","text":"It only wakes when you are close to death. When you want something so badly that dying is not enough to stop you.","mono":false,"off":440.0118,"dur":6.827,"env":"0784158866566666666642024332000001788776652022776653202754276653310000000000000000499987776554323357552366753347665316555643455555300000006632326865555655554200016656975543666654200145431076653000333210000"},"ep01x_056":{"who":"TAKUTO","text":"The axe.","mono":false,"off":447.2384,"dur":0.725,"env":"0157888998651022210000"},"ep01x_057":{"who":"SIEG","text":"The axe woke yours. Or you woke the axe. I am not sure which yet.","mono":false,"off":448.3637,"dur":4.139,"env":"08723676413329977641058876667666543100000069998877766520048523676542013332000000000489888765532333387676665233177654210100000"},"ep01x_058":{"who":"NEMU","text":"Mine is Nine Lives. I can die nine times and get back up.","mono":false,"off":452.9024,"dur":4.885,"env":"002478887643202854337877777544443221110000164410000000000000000000000001650499579766777555777788754322433221100253200001883573001643200232110001000"},"ep01x_059":{"who":"TAKUTO","text":"You died. Today. I watched you die.","mono":false,"off":458.1877,"dur":2.24,"env":"02432987666651034534876532100000035653686514322322654321100000000000"},"ep01x_060":{"who":"NEMU","text":"Mm. That was number seven. Two left. Do not look so sad. It is a good Brand. Very practical.","mono":false,"off":460.8277,"dur":7.509,"env":"0367777766544310000000000027531000544067653443432454013210000000000004238653343211000011000000000000000000035878865400265023333324322332221110100000000000000029677545300379610033566654210000100000006654443003253200230112100000"},"ep01x_061":{"who":"TAKUTO","text":"...Two left.","mono":false,"off":468.7371,"dur":0.853,"env":"00145886599875311001000000"},"ep01x_062":{"who":"NEMU","text":"Two is a lot. Most people only get one.","mono":false,"off":469.9904,"dur":3.179,"env":"042299765422005542332333321100020000000000000000058873430202144013332057655530344311001111000000"},"ep01x_063":{"who":"TAKUTO","text":"Sieg. How do I get home?","mono":false,"off":473.5691,"dur":1.557,"env":"01344788521245995789852275121477642110000000000"},"ep01x_064":{"who":"SIEG","text":"Skyfallen do not go home, Takuto. Not that I have ever heard of. I am sorry.","mono":false,"off":475.5264,"dur":5.163,"env":"02512976741167677666547676542106766648866655542032876400497423686655410000000078641365768997400365466765976655643322100000000001799876654433866554332210000"},"ep01x_065":{"who":"TAKUTO","text":"My friend fell through two years ago. From the same crossing. Haruki Shinjo. Black hair. Blue eyes.","mono":false,"off":481.0891,"dur":6.635,"env":"00146741119877311986400124431043154323554223113332100000000455434334544443011067664233221000000000000000169987677401113432443334555542244333222102455540001455443222111134554432454431100001110000000000"},"ep01x_066":{"who":"SIEG","text":"Then he could be anywhere in this world. Or nowhere. The Hunters' Guild keeps records of every Skyfallen it finds.","mono":false,"off":488.1237,"dur":6.891,"env":"088789973158568410056666656655433576665430177655555420000000003899987665665544332210000000000000776986536766521686655565300001675313316786400676533676300056535765442047656510376556566311100676544432212332000"},"ep01x_067":{"who":"TAKUTO","text":"Where is the Guild?","mono":false,"off":495.4144,"dur":1.109,"env":"0146888985413621279975311010000000"},"ep01x_068":{"who":"SIEG","text":"Ashford. Three days east. The frontier town. I am going there anyway. You two are coming with me.","mono":false,"off":496.9237,"dur":6.101,"env":"0776444214776543211159766567666654457754333201000000000583288776337866413297666655554200000000168876775676555665766300266676754544444100000000896133597665552012876665544553104543210000"},"ep01x_069":{"who":"NEMU","text":"Me?","mono":false,"off":503.4251,"dur":0.619,"env":"0048997654311110000"},"ep01x_070":{"who":"SIEG","text":"You died for him, little cat. That makes you his problem now. And his problem is my problem. That is how it works.","mono":false,"off":504.4438,"dur":6.997,"env":"068647644554311566577554455654543001575543010000000000075204765323227656558642001665544665565554544333310000000000068896410027545336555314544764445400165555335434331000000000676357542246556541004664310023332000"},"ep01x_071":{"who":"AKURO","text":"So. You can hear me now, boy. Properly. Not just in the screaming.","mono":true,"off":511.8411,"dur":4.437,"env":"01343689799853454236832267774788766566555432257999765432100002566541146643333210002468777531023454312456643333311345554444222111000000"},"ep01x_072":{"who":"TAKUTO","text":"Who are you?","mono":false,"off":516.6784,"dur":0.875,"env":"000576997533567431110000000"},"ep01x_073":{"who":"AKURO","text":"The one in the axe. The one who asked you a question. Do you remember what I asked?","mono":true,"off":517.9531,"dur":5.333,"env":"0039996455766544467777753135666442100123221013664567646556632456654332125677430111466743321233332221100001345755657665675655665445545555441123443221112210000000"},"ep01x_074":{"who":"TAKUTO","text":"What is it you want to break.","mono":false,"off":523.6864,"dur":1.579,"env":"003797898445861012344456555431257542100000000000"},"ep01x_075":{"who":"AKURO","text":"And? You never really answered. You just swung. Very satisfying. Very rude.","mono":true,"off":525.6651,"dur":5.44,"env":"01468666444686787747873579886543125687432335665421135533556531133432369877743211000000002279887865543333478787454333215776544333332211156787665532246664343221100000"},"ep01x_076":{"who":"TAKUTO","text":"I want to find Haruki.","mono":false,"off":531.5051,"dur":1.685,"env":"002685798883225876664423666556531111332110000000000"},"ep01x_077":{"who":"AKURO","text":"That is not breaking, boy. That is finding. Those are different verbs. Think about it. We have time. I have had three hundred years of it.","mono":true,"off":533.5904,"dur":9.515,"env":"0012454534333345454442000346755311246555433124676877776543211356542235444211245555565423432211000000000015588759434576521466211555321212488686765432233202675345334665564344320000154432223455310122234444543232211000000024554552123454210001234545422367753355422233454454322232122110111000"},"ep01x_078":{"who":"TAKUTO","text":"What is your name?","mono":false,"off":543.5051,"dur":1.045,"env":"01279666343444554442111000000000"},"ep01x_079":{"who":"AKURO","text":"...Akuro. Remember it. Everyone else forgot.","mono":true,"off":544.9504,"dur":3.115,"env":"0013678521234647989998534676967757745644321000002486345766577666434432124432235644321100111000"},"ep01x_080":{"who":"TAKUTO","text":"You live here? In a graveyard?","mono":false,"off":548.4651,"dur":1.707,"env":"0134238961210444322000344311255544113333210000000000"},"ep01x_081":{"who":"NEMU","text":"I am a grave scavenger. I find nice things the dead do not need, and I sell them in town for bread.","mono":false,"off":550.5717,"dur":7.637,"env":"03246766750021367876544026331344430131154100100000000000000000000000000000002594111789997420266665233310058866644300600467654100444567544200067865310002000000000000000000003356635332566621755555313311456643200111130034432110020000"},"ep01x_082":{"who":"TAKUTO","text":"That sounds illegal.","mono":false,"off":558.6091,"dur":1.237,"env":"01793034698775476545654214422110000000"},"ep01x_083":{"who":"NEMU","text":"It is very illegal. But I ask them first. I always ask. If they say no, I leave it.","mono":false,"off":560.2464,"dur":7.061,"env":"13822653400576666544432354202310000000000000000000000000034476400388652322010156521114432100233302100000000000003750289864765432255321100222101000000000000000056112763432267897677665543210000377532543311210001000"},"ep01x_084":{"who":"TAKUTO","text":"They say no?","mono":false,"off":567.7078,"dur":1.003,"env":"0178533229976666665421110000000"},"ep01x_085":{"who":"NEMU","text":"Sometimes. You can feel it. A grave that says no feels heavy. Like a held breath.","mono":false,"off":569.1104,"dur":6.229,"env":"0122687743246555544243310000000000178143975111276741210001000000000000000000028503147999876542010431023336544447888863111155543421255103210000000000000000000450364326554000044532110000000"},"ep01x_086":{"who":"NEMU","text":"The Headsman's grave always said no. For years. I tried to pull that axe out once. I hurt my back for a week.","mono":false,"off":575.7397,"dur":8.896,"env":"014223893133077765443022567654434311100078875476534222343002443221100000000000000000000000000155326886421000024320000000000000000000015814315675043002156651665310068641012222354300014443200022331000000000000000000000000275111187410025555106543201111234431342100001000"},"ep01x_087":{"who":"TAKUTO","text":"It came out for me.","mono":false,"off":585.0358,"dur":1.216,"env":"0561026977899993121444443211100000000"},"ep01x_088":{"who":"NEMU","text":"It said yes to you. I have never heard a grave say yes so loud.","mono":false,"off":586.6517,"dur":4.928,"env":"0210332697012577522230442112110000000000000000000000000000003998710589960564116765252002356766640342225443221000000000078433223244443444321110002000"},"ep01x_089":{"who":"NEMU","text":"Takuto. Thank you. For breaking the thing that was killing me.","mono":false,"off":591.9797,"dur":4.352,"env":"01226630216524315443221000000000000000289851211211000000000000000000001351068883036887455000188865554431035320311655543222211000000"},"ep01x_090":{"who":"TAKUTO","text":"You died anyway.","mono":false,"off":596.7318,"dur":1.173,"env":"002431797776632045554443211100000000"},"ep01x_091":{"who":"NEMU","text":"Only a little. You got there in time for the rest of me.","mono":false,"off":598.3051,"dur":3.84,"env":"05998788654422442210000000000000000000000000055049853200266544566414411366654332100011431531555324340430003110000000"},"ep01x_092":{"who":"NEMU","text":"This is everything I own. A blanket. A spoon. A music box that plays half a song.","mono":false,"off":602.5451,"dur":6.72,"env":"0262211353210378402441004443333443135643211000000000000000000000262044566653021110001000000000000254223102787643210000000000000000000028888897444501004543210012100320020444322122444102332314332110000000"},"ep01x_093":{"who":"TAKUTO","text":"Half a song?","mono":false,"off":609.6651,"dur":1.003,"env":"0014776137332298765321110000000"},"ep01x_094":{"who":"NEMU","text":"The other half is broken. Maybe you could break it back.","mono":false,"off":611.0678,"dur":3.755,"env":"01312794576322265643100000065520035554102111100000000000000000000000368999815754345113720056640231004432210001000"},"ep01x_095":{"who":"TAKUTO","text":"That is not how breaking works.","mono":false,"off":615.2224,"dur":1.771,"env":"004897795436887644456663139772114444344210013320000000"},"ep01x_096":{"who":"NEMU","text":"You do not know that yet.","mono":false,"off":617.3931,"dur":1.451,"env":"00052598797652000587755034310003422100030000"},"ep01x_097":{"who":"NEMU","text":"Goodbye, everyone. I am going to Ashford. Do not let anyone else take your nice things while I am gone.","mono":false,"off":619.2437,"dur":7.317,"env":"1140018755543200000029811343001110000000000000000000000000000014787876633787776515200565314441001000001000000000000000000003467996530028862779877644564323330412540021455555533432045543222243003433344443330354321100000000"},"ep01x_098":{"who":"SIEG","text":"Takuto. Let me see the axe. Just look. I will not touch it.","mono":false,"off":626.9611,"dur":4.117,"env":"0197663179764277666666642004752478632577575335665431033221000005976530488764100000000000279877787655531002297422325321100000"},"ep01x_099":{"who":"SIEG","text":"Three hundred years old. Older. Look at the marks on the haft.","mono":false,"off":631.4784,"dur":3.883,"env":"013996577676564576556676665555667544432100000000058777776586665200000006951742677765554124346666554336765432110110000"},"ep01x_100":{"who":"SIEG","text":"This is the Headsman's Axe. The one from the stories.","mono":false,"off":635.7611,"dur":3.221,"env":"0797532015876547775786554477666664211577542003321000000005988766652276666523206766765443322210000"},"ep01x_101":{"who":"TAKUTO","text":"What stories?","mono":false,"off":639.3824,"dur":1.024,"env":"0148813411999987543321111000000"},"ep01x_102":{"who":"SIEG","text":"Stories you tell children so they stay out of graveyards. They mostly do not work. Ask Nemu.","mono":false,"off":640.8064,"dur":5.845,"env":"02129766555554476312775531342866545655443226645654320266555555564310575556445543333322310000000038998666432056654776555554100467664310000000000000057764330006877665544332210000"},"ep01x_103":{"who":"SIEG","text":"Do not swing it at anything you love, Takuto. And if it ever talks to you, tell me.","mono":false,"off":647.0517,"dur":5.547,"env":"08988655313434168666555654200366300577663156667666665566655554431000000026966630019874226865432210000000000006998429741037546530327754204402476665542135976554332110000"},"ep01x_104":{"who":"TAKUTO","text":"...Okay.","mono":false,"off":652.9984,"dur":0.811,"env":"0136993122899653211000000"},"ep01x_105":{"who":"AKURO","text":"Liar. Ha. We are going to get along so well, boy.","mono":true,"off":654.2091,"dur":3.264,"env":"02467776657964212235775321014699954899633324775553557877654445556885335756654311255444422211100000"},"ep01x_106":{"who":"NEMU","text":"How far is Ashford?","mono":false,"off":657.8731,"dur":1.387,"env":"001894110176776654431058652433100211111000"},"ep01x_107":{"who":"SIEG","text":"Three days.","mono":false,"off":659.6598,"dur":1.024,"env":"0028998666668766765554432110000"},"ep01x_108":{"who":"NEMU","text":"Can you carry me for two of them?","mono":false,"off":661.0838,"dur":1.664,"env":"01169998103135777766545421112006317654110211100000"},"ep01x_109":{"who":"SIEG","text":"Rank A Hunters do not carry cats.","mono":false,"off":663.1477,"dur":2.709,"env":"0497666621667547765425776665531000000003988765543100129666665301287643210232210000"},"ep01x_110":{"who":"NEMU","text":"I died yesterday.","mono":false,"off":666.2571,"dur":1.323,"env":"0039930479778876110377344244422311100000"},"ep01x_111":{"who":"SIEG","text":"...One day. I will carry you for one day.","mono":false,"off":667.9797,"dur":2.411,"env":"0799766756877767620000000798776313786666666775226767776667646544332210000"},"ep01x_112":{"who":"NEMU","text":"Mm. Deal.","mono":false,"off":670.7904,"dur":1.195,"env":"046976666665542000003455322111100000"},"ep01x_113":{"who":"TAKUTO","text":"Is everything in this world trying to kill us?","mono":false,"off":672.3851,"dur":2.368,"env":"024320057932564004433334443320134444420111443332201045332100111100000000"},"ep01x_114":{"who":"SIEG","text":"Only most things. The rest are trying to sell you something.","mono":false,"off":675.1531,"dur":3.52,"env":"0798876677776667531002877776555543100000000029999866633200267524497676476332576667676432287653005433210000"},"ep01x_115":{"who":"SIEG","text":"Watch the treeline. Fiends like dusk. Ashen Hounds, mostly. Small. Mean. Afraid of fire.","mono":false,"off":679.0731,"dur":6.08,"env":"069763133017434597777665666530000069877766535766420001876433331000000000000006766545777857655666665437866663204776533332697666655420018987776554200000066215977757631005865544322210000"},"ep01x_116":{"who":"TAKUTO","text":"I do not have fire.","mono":false,"off":685.5531,"dur":1.216,"env":"0369477999857952221987653221110000000"},"ep01x_117":{"who":"SIEG","text":"You have an axe that broke something unbreakable. I think the Hounds will be very polite to you.","mono":false,"off":687.1691,"dur":5.568,"env":"069998646652035555420243320000027432088664214327654136662015666654665552055243321000000000000388258630565476555665653210000166786547655565203865655631003165444322100000"},"ep01x_118":{"who":"NEMU","text":"Takuto. What is your world like?","mono":false,"off":693.1371,"dur":2.283,"env":"022675011574051454321000000000000007956855434542356654301122210001000"},"ep01x_119":{"who":"TAKUTO","text":"Loud. Bright. Too many people. Trains every three minutes.","mono":false,"off":695.8197,"dur":3.371,"env":"013689877752116999751014365555430114420132110000000133865665544425621343111134444544311000233200000000"},"ep01x_120":{"who":"NEMU","text":"What is a train?","mono":false,"off":699.5904,"dur":1.067,"env":"00399488544403521788753322000000"},"ep01x_121":{"who":"TAKUTO","text":"A metal house that runs on rails. Very fast. You can sleep in it.","mono":false,"off":701.0571,"dur":4.075,"env":"003577898897323467764320553135665534655444455664311101110000117978751116876421123100000232136525430354200332210000000000000"},"ep01x_122":{"who":"NEMU","text":"A house you can sleep in, that also takes you places? That is the best thing I have ever heard.","mono":false,"off":705.5317,"dur":7.36,"env":"03322268974332246213764433147750046876432110000000000000000265203998543356504315402332510314332222110002210000000000000000000000000000000000798743100000000000874206410776522220100587654432200488761315961343114432110001000"},"ep01x_123":{"who":"TAKUTO","text":"There are vending machines on every corner. Boxes that give you drinks at two in the morning.","mono":false,"off":713.2917,"dur":5.547,"env":"00155776211486565254333332433223333333223333320013421232011124443211100000000000000006898300222432201531002421222112433112132000231243322212222233333211100000000000000"},"ep01x_124":{"who":"NEMU","text":"For free?","mono":false,"off":719.2384,"dur":0.853,"env":"00016732111589864321000000"},"ep01x_125":{"who":"TAKUTO","text":"For coins. One of them has coffee milk. That is where I fed the cat.","mono":false,"off":720.4918,"dur":3.989,"env":"001620325899875443323212455642464444544401113774111333332210000000000000046657442255555444111254211301124431100000000000"},"ep01x_126":{"who":"NEMU","text":"What is the cat called?","mono":false,"off":724.8811,"dur":1.429,"env":"0028954985430250211366430110214443211102000"},"ep01x_127":{"who":"TAKUTO","text":"Coffee. Haruki wanted Mister Tuesday.","mono":false,"off":726.7104,"dur":2.453,"env":"01159984112542100001477667620124433454443334331121031443221022110000000000"},"ep01x_128":{"who":"NEMU","text":"Mister Tuesday is a much better name.","mono":false,"off":729.5638,"dur":2.603,"env":"0086431464034169864432422100000000000000284799886302420367744666565432110000000"},"ep01x_129":{"who":"TAKUTO","text":"...Everybody says that.","mono":false,"off":732.5664,"dur":1.387,"env":"000269526852888655333265421144321000000000"},"ep01x_130":{"who":"NEMU","text":"Who is feeding Coffee now?","mono":false,"off":734.3531,"dur":1.557,"env":"00187854420016795575422124652112332332210000000"},"ep01x_131":{"who":"TAKUTO","text":"...Nobody.","mono":false,"off":736.3104,"dur":0.896,"env":"024567893287652322100000000"},"ep01x_132":{"who":"NEMU","text":"Then we had better find your friend quickly. Cats do not wait forever.","mono":false,"off":737.6064,"dur":4.8,"env":"016998764210156750067635411136677664332111457654340021550010111000000000000000000000000000000212476310034405688986440001764302111333443111110000"},"ep01x_133":{"who":"SIEG","text":"One. Two. Three...","mono":false,"off":742.8064,"dur":1.344,"env":"07987755553142977665311258887644443200000"},"ep01x_134":{"who":"SIEG","text":"Eleven. And now two more. Thirteen.","mono":false,"off":744.5504,"dur":2.517,"env":"0489777545555542004888765556414368667766555444200000000298763327755433210000"},"ep01x_135":{"who":"SIEG","text":"A Rift that opens sideways. A Skyfallen boy with the Headsman's Axe. And static in the air, like before Grey Hollow.","mono":false,"off":747.4678,"dur":7.808,"env":"0799987653110000673037874007776643334655567544544432332000000000000764405866662037667667753565556555556630664696544268666652126764200343200000000002995441186655641068877630257665554100000002887520007621587643178766666645765544432210000"},"ep01x_136":{"who":"SIEG","text":"...I do not like this at all.","mono":false,"off":755.6757,"dur":1.813,"env":"0489988987766652048877752006985430059879987644443210000"}}};
